def _write_stream(mode, text, is_err=False):
    if mode == 0:
        return
    if mode == 1:
        sys.stdout.write(text); sys.stdout.flush()
    elif mode == 2:
        sys.stderr.write(text); sys.stderr.flush()

def out(text=""):
    _write_stream(OUT_MODE, text)

def outln(text=""):
