def parse_include_pattern_spec(spec):
    # spec after -i / -x / -ai / -ax : forms: [r[-|0]][m[-|2]][w[-]] then either @list or !wildcard or ??? 
    # returns (recurse, wildcard_or_list, is_listfile)
    recurse=None; i=0
    # parse modifiers at start if spec starts with r,m,w and followed by options then !/@
    # Simplistic: scan prefix modifiers until we encounter ! or @ or end
    # modifiers pattern: r[-0]? m[-2]? w[-]?
    while i < len(spec):
        c=spec[i]
        if c in 'rmw':
            # check next
            if c=='r':
                if i+1<len(spec) and spec[i+1]=='-': recurse=False; i+=2
                elif i+1<len(spec) and spec[i+1]=='0': recurse='0'; i+=2
                else: recurse=True; i+=1
            elif c=='m':
                if i+1<len(spec) and spec[i+1] in '-2': i+=2
                else: i+=1
            elif c=='w':
                if i+1<len(spec) and spec[i+1]=='-': i+=2
                else: i+=1
            # after modifier, if next char is !/@ or rest is wildcard, continue? If remainder starts with !/@ break
            if i<len(spec) and spec[i] in '!@':
                break
