        allowed = ('utf-8','utf-16le','utf-16be','win','dos')
        if val=='' or (val.lower() not in allowed and not re.match(r'^\d+$', val)):
            raise CmdLineError('charset', f"Unsupported charset:\n{val.lower()}")
