    if low.startswith('sdel'):
        if low!='sdel': raise CmdLineError('long', f"Too long switch:\n{token}")
        opts.sdel=True; return
    if low.startswith('seml'):
        # seml[.]
        return
    if low.startswith('sfx'):
        opts.sfx_specified=True; opts.sfx=body[3:]; return
    if low.startswith('stm'):
        val=body[3:]
        if val=='' : raise CmdLineError('short', f"Too short switch:\n{token}")
        if not re.match(r'^[0-9a-fA-F]+$', val):
            raise CmdLineError('post', f"Unsupported switch postfix -stm\n{val}")
        return
    if low.startswith('stx'):
        if len(body)<=3: raise CmdLineError('short', f"Too short switch:\n{token}")
        opts.stx_types.append(body[3:]); return
    # other s switches exact or with values
    if low.startswith('stl'):
        if low!='stl': raise CmdLineError('long', f"Too long switch:\n{token}")
        opts.stl=True; return
    if low.startswith('slt'):
        if low!='slt': raise CmdLineError('long', f"Too long switch:\n{token}")
        opts.slt=True; return
    if low.startswith('slp'):
        if low!='slp': raise CmdLineError('long', f"Too long switch:\n{token}")
        return
    if low.startswith('snh'):
        if low!='snh': raise CmdLineError('long', f"Too long switch:\n{token}")
        opts.snh=True; return
    if low.startswith('snl'):
        if low!='snl': raise CmdLineError('long', f"Too long switch:\n{token}")
        opts.snl=True; return
    if low.startswith('sni'):
        if low!='sni': raise CmdLineError('long', f"Too long switch:\n{token}")
        return
    if low.startswith('sns'):
        if low not in ('sns','sns-'): raise CmdLineError('long', f"Too long switch:\n{token}")
        return
    if low.startswith('spd'):
        if low!='spd': raise CmdLineError('long', f"Too long switch:\n{token}")
        opts.spd=True; return
    if low.startswith('spe'):
        if low!='spe': raise CmdLineError('incorr', f"Incorrect switch postfix:\n{token}")
        opts.spe=True; return
    if low.startswith('spf'):
        val=body[3:]
        if val=='': opts.spf=1
        elif val=='2': opts.spf=2
        else: raise CmdLineError('incorr', f"Incorrect switch postfix:\n{token}")
        return
    if low.startswith('ssc'):
        if low=='ssc': opts.case_sensitive=True; opts.ssc=True
        elif low=='ssc-': opts.case_sensitive=False; opts.ssc=False
        else: raise CmdLineError('long', f"Too long switch:\n{token}")
        return
    if low.startswith('sse'):
        if low!='sse': raise CmdLineError('long', f"Too long switch:\n{token}")
        opts.sse=True; return
    if low.startswith('ssp'):
        if low!='ssp': raise CmdLineError('long', f"Too long switch:\n{token}")
        return
    if low.startswith('ssw'):
        if low!='ssw': raise CmdLineError('long', f"Too long switch:\n{token}")
        opts.ssw=True; return
    if low.startswith('sa'):
        val=body[2:]
        if val=='':
            raise CmdLineError('short', f"Too short switch:\n{token}")
        if len(val)!=1 or val.lower() not in 'aes':
