            opts.bb_level=int(rest)
        else:
            raise CmdLineError('post', f"Unsupported switch postfix -bb\n{rest}")
        return
    if low.startswith('bd'):
        if low!='bd': raise CmdLineError('long', f"Too long switch:\n{token}")
        opts.bd=True; return
    if low.startswith('bt'):
        if low!='bt': raise CmdLineError('long', f"Too long switch:\n{token}")
        opts.bt=True; return
    if low.startswith('bs'):
