            raise CmdLineError('short', f"Too short switch:\n{token}")
        kind=body[2]; val=body[3]
        if kind not in 'oep' or val not in '012' or len(body)!=4:
            raise CmdLineError('incorr', f"Incorrect switch postfix:\n{token}")
        global OUT_MODE, ERR_MODE
        if kind=='o': 
            # update global later? set now as module globals via opts as well
            opts._bso=int(val)
            OUT_MODE=int(val)
        elif kind=='e':
            opts._bse=int(val); ERR_MODE=int(val)
        else:
            opts._bsp=int(val)
        return
    # a switches
    if low.startswith('ai'):
        add_include_exclude(opts,'ai',body[2:]); return
    if low.startswith('ax'):
        add_include_exclude(opts,'ax',body[2:]); return
    if low.startswith('ao'):
        if len(body)<=2: raise CmdLineError('short', f"Too short switch:\n{token}")
        if len(body)!=3 or body[2].lower() not in 'astu':
            raise CmdLineError('incorr', f"Incorrect switch postfix:\n{token}")
        opts.overwrite_mode=body[2].lower(); return
    if low.startswith('an'):
        if low!='an': raise CmdLineError('long', f"Too long switch:\n{token}")
        opts.an=True; return
    # single etc
    if low.startswith('i') and not low.startswith('i'):
        pass
    # -i include filenames ; note commands 'i' is a command name, but -i is switch
    if body[0]=='i':
        add_include_exclude(opts,'i',body[1:]); return
    if body[0]=='x' and low[0]=='x':
        # -x exclude; but careful -x as ??? it's switch
        add_include_exclude(opts,'x',body[1:]); return
    if body[0]=='m':
        if len(body)<=1: raise CmdLineError('short', f"Too short switch:\n{token}")
        parse_method_param(opts, body[1:]); return
    if body[0]=='o':
        if len(body)<=1: raise CmdLineError('short', f"Too short switch:\n{token}")
        opts.output_dir=body[1:]; return
    if body[0]=='p':
        if len(body)==1:
            opts.password_prompt=True; opts.password=None
        else:
            opts.password=body[1:]; opts.password_prompt=False
        return
    if body[0]=='r':
        if low=='r': opts.recurse_mode=True; opts.recurse_specified=True
        elif low=='r-': opts.recurse_mode=False; opts.recurse_specified=True
        elif low=='r0': opts.recurse_mode='0'; opts.recurse_specified=True
        else: raise CmdLineError('incorr', f"Incorrect switch postfix:\n{token}")
        return
    if body[0]=='t':
        if len(body)<=1: raise CmdLineError('short', f"Too short switch:\n{token}")
        opts.type=body[1:]; return
    if body[0]=='u':
        opts.update_options_raw=body[1:]; return
    if body[0]=='v':
        if len(body)<=1: raise CmdLineError('short', f"Too short switch:\n{token}")
        opts.volume_str=body[1:]; opts.volume=parse_volume_size(body[1:]); return
    if body[0]=='w':
        opts.workdir=body[1:]; return
    if body[0]=='y':
        if low!='y': raise CmdLineError('long', f"Too long switch:\n{token}")
        opts.assume_yes=True; return
    # unknown
    raise CmdLineError('u', f"Unknown switch:\n{token}")

def parse_args(argv):
    opts=Options()
    positionals=[]
    stop=False
    for token in argv:
        if stop:
            positionals.append(token); continue
        if token=="--":
            stop=True; opts.stop_switches=True; continue
        if token=="--help":
            opts.help=True; continue
        if token.startswith('-') and token!="-" or token=="-":
            # '-' alone is treated as unknown switch in original
            # But note token == '-' will go here
            parse_switch_token(opts, token); continue
        else:
            positionals.append(token)
    # positionals: first is command if not set
    if positionals:
        # command is first positional regardless? Switches before command already handled
        opts.command = positionals[0]
        opts.raw_positionals = positionals[1:]
    return opts

