def lzma2_dict_from_prop(prop):
    if prop==40: return 0xFFFFFFFF
    if prop>40: raise ValueError("Bad LZMA2 prop")
    return (2 + (prop & 1)) << (prop//2 + 11)

def lzma2_prop_from_dict(dsize):
    # find prop
    if dsize==0xFFFFFFFF: return 40
    for prop in range(41):
        if lzma2_dict_from_prop(prop)==dsize:
            return prop
    # round up to next representable
    for prop in range(41):
        if lzma2_dict_from_prop(prop)>=dsize:
            return prop
    return 40

def dict_display(dsize):
    if dsize is None: return ""
    if dsize>=4096 and (dsize & (dsize-1))==0:
        return str(dsize.bit_length()-1)
    if dsize % (1024*1024)==0:
        return f"{dsize//(1024*1024)}m"
    if dsize % 1024==0:
        return f"{dsize//1024}k"
    return str(dsize)

