    cid=coder['id']; props=coder['props'] or b''
    if cid==b'\x00': return ("Copy","Copy")
    if cid==bytes.fromhex('030101'):
        dsize=struct.unpack('<I', props[1:5])[0] if len(props)>=5 else 0
        name=f"LZMA:{dict_display(dsize)}"
