def lzma2_dict_from_prop(prop):
    if prop==40: return 0xFFFFFFFF
    if prop>40: raise ValueError("Bad LZMA2 prop")
    return (2 + (prop & 1)) << (prop//2 + 11)

def lzma2_prop_from_dict(dsize):
    # find prop
    if dsize==0xFFFFFFFF: return 40
    for prop in range(41):
        if lzma2_dict_from_prop(prop)==dsize:
            return prop
    # round up to next representable
    for prop in range(41):
        if lzma2_dict_from_prop(prop)>=dsize:
            return prop
    return 40

def dict_display(dsize):
    if dsize is None: return ""
    if dsize>=4096 and (dsize & (dsize-1))==0:
        return str(dsize.bit_length()-1)
    if dsize % (1024*1024)==0:
        return f"{dsize//(1024*1024)}m"
    if dsize % 1024==0:
        return f"{dsize//1024}k"
    return str(dsize)

def coder_name_and_detail(coder, detailed=True):
    cid=coder['id']; props=coder['props'] or b''
    if cid==b'\x00': return ("Copy","Copy")
    if cid==bytes.fromhex('030101'):
        dsize=struct.unpack('<I', props[1:5])[0] if len(props)>=5 else 0
        name=f"LZMA:{dict_display(dsize)}"
        return (name,name)
    if cid==b'\x21':
        dsize=lzma2_dict_from_prop(props[0]) if props else 4096
        name=f"LZMA2:{dict_display(dsize)}"
        return (name,name)
    if cid==b'\x03':
        dist=(props[0]+1) if props else 1
        if detailed: return (f"Delta:{dist}", f"Delta:{dist}")
        else: return ("Delta","Delta")
    if cid==bytes.fromhex('03030103'): return ("BCJ","BCJ")
    if cid==bytes.fromhex('03030205'): return ("PPC","PPC")
    if cid==bytes.fromhex('03030401'): return ("IA64","IA64")
    if cid==bytes.fromhex('03030501'): return ("ARM","ARM")
    if cid==bytes.fromhex('03030701'): return ("ARMT","ARMT")
    if cid==bytes.fromhex('03030805'): return ("SPARC","SPARC")
    if cid==bytes.fromhex('040108'): return ("Deflate","Deflate")
    if cid==bytes.fromhex('040109'): return ("Deflate64","Deflate64")
    if cid==bytes.fromhex('040202'): return ("BZip2","BZip2")
    if cid==bytes.fromhex('030401'): return ("PPMD","PPMD")
    if cid==bytes.fromhex('06f10701'):
        cycles=(props[0] & 0x3F) if props else 0
        if detailed: return ("7zAES", f"7zAES:{cycles}")
        else: return ("7zAES","7zAES")
    if cid==bytes.fromhex('06f00181'): return ("AES256CBC","AES256CBC")
    if cid in (b'\x0a',): return ("ARM64","ARM64")
    if cid in (b'\x0b',): return ("RISCV","RISCV")
    # generic
    hexid=cid.hex().upper()
    return (hexid,hexid)

def sz_filter_for_coder(coder):
    cid=coder['id']; props=coder['props'] or b''
    if cid==bytes.fromhex('030101'):
        b=props[0] if props else 0x5D
        lc=b%9; rem=b//9; lp=rem%5; pb=rem//5
        dsize=struct.unpack('<I', props[1:5])[0] if len(props)>=5 else 1<<24
        return {'id':lzma.FILTER_LZMA1,'dict_size':dsize,'lc':lc,'lp':lp,'pb':pb}
    if cid==b'\x21':
        dsize=lzma2_dict_from_prop(props[0]) if props else 4096
        if dsize==0xFFFFFFFF: dsize=1<<30
        return {'id':lzma.FILTER_LZMA2,'dict_size':dsize}
    if cid==b'\x03':
        return {'id':lzma.FILTER_DELTA,'dist':(props[0]+1) if props else 1}
    if cid==bytes.fromhex('03030103'): return {'id':lzma.FILTER_X86}
    if cid==bytes.fromhex('03030205'): return {'id':lzma.FILTER_POWERPC}
    if cid==bytes.fromhex('03030401'): return {'id':lzma.FILTER_IA64}
    if cid==bytes.fromhex('03030501'): return {'id':lzma.FILTER_ARM}
    if cid==bytes.fromhex('03030701'): return {'id':lzma.FILTER_ARMTHUMB}
    if cid==bytes.fromhex('03030805'): return {'id':lzma.FILTER_SPARC}
    return None

def sz_decode_coder(coder, data, unpack_size, password, opts):
    cid=coder['id']; props=coder['props'] or b''
    if cid==b'\x00':
        return data[:unpack_size] if unpack_size is not None else data
    if cid==bytes.fromhex('030101'):
        filt=sz_filter_for_coder(coder)
        d=lzma.LZMADecompressor(format=lzma.FORMAT_RAW, filters=[filt])
        out=d.decompress(data)
        if unpack_size is not None and len(out)>unpack_size: out=out[:unpack_size]
        return out
    if cid==b'\x21':
        filt=sz_filter_for_coder(coder)
        d=lzma.LZMADecompressor(format=lzma.FORMAT_RAW, filters=[filt])
        out=d.decompress(data)
        if unpack_size is not None and len(out)>unpack_size: out=out[:unpack_size]
        return out
    if cid==bytes.fromhex('040108') or cid==bytes.fromhex('040109'):
        d=zlib.decompressobj(-15)
        out=d.decompress(data); out+=d.flush()
        return out[:unpack_size] if unpack_size is not None else out
    if cid==bytes.fromhex('040202'):
        d=bz2.BZ2Decompressor(); out=d.decompress(data)
        return out[:unpack_size] if unpack_size is not None else out
    if cid==bytes.fromhex('06f10701'):
        if password is None:
            raise NeedPassword()
        if len(props)<2: raise ValueError("Bad AES props")
        cycles=props[0] & 0x3F
        # Interpretation: props layout 53 0F + salt(8)+iv(8)
        salt=props[2:10]; iv=props[10:18]+b'\x00'*8 if len(props)>=18 else (props[2:].ljust(16,b'\x00'))
        # Alternate if salt is 16 bytes (when iv size 0): check second byte? Our earlier spec guess keeps 8.
        key=derive_7z_key(password, salt, cycles)
        dec=aes_cbc_decrypt(key, iv, data)
        return dec[:unpack_size] if unpack_size is not None else dec
    if cid==bytes.fromhex('06f00181'):
        # AES256CBC for ??? salt/iv format similar to 7zAES but props first bytes?
        raise ValueError("AES256CBC not supported")
    if cid==b'\x03':
        # Delta decode standalone
        dist=(props[0]+1) if props else 1
        out=bytearray(data)
        for i in range(len(out)):
            if i>=dist: out[i]=(out[i]+out[i-dist])&0xFF
        return bytes(out[:unpack_size]) if unpack_size is not None else bytes(out)
    # filters alone via lzma
    filt=sz_filter_for_coder(coder)
    if filt is not None:
        d=lzma.LZMADecompressor(format=lzma.FORMAT_RAW, filters=[filt])
        out=d.decompress(data)
        return out[:unpack_size] if unpack_size is not None else out
    raise ValueError(f"Unsupported coder {cid.hex()}")

class NeedPassword(Exception):
    pass
class HeadersEncryptedError(Exception):
    pass

def sz_decode_folder(folder, packed_data, password, opts):
    # Try combined lzma filter chain if applicable and no AES/copy etc interleaved
    coders=folder.coders
    # if multiple coders and all filterable
    if len(coders)>1 and all(sz_filter_for_coder(c) is not None for c in coders):
        # encoding order is reverse of coders list
        filters=[sz_filter_for_coder(c) for c in reversed(coders)]
        d=lzma.LZMADecompressor(format=lzma.FORMAT_RAW, filters=filters)
        out=d.decompress(packed_data)
        final_size=folder.unpack_sizes[-1] if folder.unpack_sizes else len(out)
        return out[:final_size]
    data=packed_data
    for idx,coder in enumerate(coders):
        outsize=folder.unpack_sizes[idx] if idx < len(folder.unpack_sizes) else None
        data=sz_decode_coder(coder, data, outsize, password, opts)
    return data

def sz_parse_files(d,i, streams):
    numfiles,i=sz_read_num(d,i)
    props={}
    # defaults
    names=[f"file{k}" for k in range(numfiles)]
    empty_stream=None; empty_file=None; anti=None
    mtimelist=[None]*numfiles; atimelist=[None]*numfiles; ctimelist=[None]*numfiles
    attrs=[None]*numfiles
    file_crcs_defined=None; file_crcs=[]
    while True:
        if i>=len(d): break
        pid=d[i]; i+=1
        if pid==0: break
        size,i=sz_read_num(d,i)
        start=i
        data_prop=d[i:i+size]
        if pid==0x11:  # Name
            if data_prop:
                ext=data_prop[0]
                if ext==0:
                    pos=1; names=[]
                    for _ in range(numfiles):
                        j=start+pos
                        # find utf16 null terminator aligned
                        k=j
                        while k+1 < start+size and d[k:k+2]!=b'\x00\x00': k+=2
                        names.append(d[j:k].decode('utf-16le','surrogateescape'))
                        pos=(k-start)+2
                    props['names']=names
                else:
                    # external names stream not supported
                    props['names']=names
        elif pid==0x0E:
            empty_stream=sz_bitvector_decode(data_prop, numfiles)
        elif pid==0x0F:
            # number of empty stream entries
            cnt=sum(1 for x in (empty_stream or []) if x)
            empty_file=sz_bitvector_decode(data_prop, cnt if cnt else numfiles)
        elif pid==0x10:
            cnt=sum(1 for x in (empty_stream or []) if x)
            anti=sz_bitvector_decode(data_prop, cnt if cnt else numfiles)
        elif pid in (0x12,0x13,0x14):
            pos=0
            if pos>=len(data_prop): defined=[]
            else:
                alldef=data_prop[pos]; pos+=1
                if alldef:
                    defined=[True]*numfiles
                else:
                    defined=sz_bitvector_decode(data_prop[pos:pos+(numfiles+7)//8], numfiles); pos+=(numfiles+7)//8
                ext=data_prop[pos]; pos+=1
                times=[]
                for idx in range(numfiles):
                    if idx < len(defined) and defined[idx]:
                        if ext==0:
                            ft=struct.unpack_from('<Q', data_prop, pos)[0]; pos+=8; times.append(ft)
                        else: times.append(None)
                    else: times.append(None)
                if pid==0x14: mtimelist=times
                elif pid==0x13: atimelist=times
                elif pid==0x12: ctimelist=times
        elif pid==0x15:
            pos=0
            alldef=data_prop[pos]; pos+=1
            if alldef: defined=[True]*numfiles
            else:
                defined=sz_bitvector_decode(data_prop[pos:pos+(numfiles+7)//8], numfiles); pos+=(numfiles+7)//8
            ext=data_prop[pos]; pos+=1
            attrs=[]
            for idx in range(numfiles):
                if defined[idx]:
                    attrs.append(struct.unpack_from('<I', data_prop, pos)[0]); pos+=4
                else: attrs.append(None)
        elif pid==0x0A:
            pos=0; alldef=data_prop[pos]; pos+=1
            # CRCs for files with stream: count = numfiles - empty count
            emptycnt=sum(1 for x in (empty_stream or []) if x)
            n=numfiles-emptycnt
            if alldef: defined=[True]*n
            else:
                defined=sz_bitvector_decode(data_prop[pos:pos+(n+7)//8], n); pos+=(n+7)//8
            file_crcs=[]
            for has in defined:
                if has:
                    file_crcs.append(struct.unpack_from('<I', data_prop, pos)[0]); pos+=4
                else: file_crcs.append(None)
            file_crcs_defined=defined
        else:
            # dummy / unknown skip
            pass
        i=start+size
    if 'names' in props: names=props['names']
    return {
        'numfiles':numfiles,'names':names,'empty_stream':empty_stream,'empty_file':empty_file,'anti':anti,
        'mtime':mtimelist,'atime':atimelist,'ctime':ctimelist,'attrs':attrs,'file_crcs':file_crcs
    }, i

def sz_parse_header_bytes(hdr, archive_data, opts, password, path_display):
    # hdr may be encoded or plain; returns Archive entries etc, streams
    if not hdr:
        raise ValueError("Empty header")
    if hdr[0]==0x17:
        streams,i=sz_parse_streams(hdr,1)
        if not streams.folders: raise ValueError("Encoded header without folder")
        folder=streams.folders[0]
        packpos=streams.packpos; packsize=folder.pack_size or 0
        packed=archive_data[32+packpos:32+packpos+packsize]
        # Determine if AES in folder: if so need password
        try:
            decoded=sz_decode_folder(folder, packed, password, opts)
        except NeedPassword:
            raise
        except Exception as e:
            # if AES and password wrong, decoding may yield garbage; treat as headers error if AES present
            if any(c['id']==bytes.fromhex('06f10701') for c in folder.coders):
                raise HeadersEncryptedError(str(e))
            raise
        # verify folder CRC
        if folder.crc is not None:
            if (zlib.crc32(decoded)&0xffffffff)!=folder.crc:
                if any(c['id']==bytes.fromhex('06f10701') for c in folder.coders):
                    raise HeadersEncryptedError("CRC mismatch in encrypted header")
                # otherwise ignore?
        # decoded should be a plain header
        arch, main_streams, header_streams_for_size = sz_parse_plain_header(decoded, archive_data, opts, password, path_display)
        arch.headers_stream_pack_size=packsize
        arch.headers_stream_info=streams
        return arch
    elif hdr[0]==0x01:
        arch, main_streams, _ = sz_parse_plain_header(hdr, archive_data, opts, password, path_display)
        return arch
    else:
        raise ValueError("Bad header id")

def sz_parse_plain_header(hdr, archive_data, opts, password, path_display):
    i=1
    main_streams=None
    arch=Archive(); arch.type='7z'; arch.path_display=path_display
    # skip archive properties
    while i < len(hdr):
        b=hdr[i]
        if b==0x02:  # ArchiveProperties
            i+=1
            while i < len(hdr):
                pid=hdr[i]; i+=1
                if pid==0: break
                sz,i=sz_read_num(hdr,i); i+=sz
            continue
        elif b==0x04:
            main_streams,i=sz_parse_streams(hdr,i+1)
            continue
        elif b==0x05:
            fileinfo,i=sz_parse_files(hdr,i+1, main_streams)
            break
        elif b==0x03:
            # AdditionalStreamsInfo: parse and ignore
            _,i=sz_parse_streams(hdr,i+1)
            continue
        else:
            break
    else:
        fileinfo={'numfiles':0,'names':[],'empty_stream':None,'empty_file':None,'anti':None,'mtime':[],'atime':[],'ctime':[],'attrs':[],'file_crcs':[]}
    # Build entries
    entries=[]
    names=fileinfo['names']; num=fileinfo['numfiles']
    empty_stream=fileinfo['empty_stream'] or [False]*num
    empty_file=fileinfo['empty_file']; anti=fileinfo['anti']
    # map empty file/anti indices
    empty_idx_map={}
    efi=0
    for idx in range(num):
        if empty_stream[idx]:
            is_empty_file=None; is_anti=False
            if empty_file is not None and efi < len(empty_file): is_empty_file=empty_file[efi]
            if anti is not None and efi < len(anti): is_anti=anti[efi]
            empty_idx_map[idx]=(is_empty_file,is_anti)
            efi+=1
    # decode folders
    folder_datas=[]
    folder_file_assignments=[]  # per folder list of file indices assigned
    if main_streams is not None:
        packed_offset=main_streams.packpos
        data_ptr=32+packed_offset
        # we will decode later per need
        # Determine file indices with stream in order
        stream_file_indices=[idx for idx in range(num) if not empty_stream[idx]]
        # assign to folders
        ptr=0
        for fi,folder in enumerate(main_streams.folders):
            cnt=folder.sub_count
            assigned=stream_file_indices[ptr:ptr+cnt]; ptr+=cnt
            folder_file_assignments.append(assigned)
            packsize=folder.pack_size or 0
            packed=archive_data[data_ptr:data_ptr+packsize]; data_ptr+=packsize
            # decode
            try:
                decoded=sz_decode_folder(folder, packed, password, opts)
            except NeedPassword:
                raise
            except Exception as e:
                # store exception marker to propagate as data error when extracting, but for listing we can still list with decoded empty
                # Raise a special error carrying folder index
                raise SzDataError(str(e), fi)
            folder_datas.append(decoded)
    # Build entries
    file_crc_ptr=0
    # substream splits
    folder_for_file={}
    offset_in_folder={}
    size_in_folder={}
    for fi,folder in enumerate(main_streams.folders if main_streams else []):
        assigned=folder_file_assignments[fi]
        decoded=folder_datas[fi]
        sizes=[]
        if len(assigned)>0:
            if folder.sub_sizes and len(folder.sub_sizes)==len(assigned)-1:
                sizes=list(folder.sub_sizes)+[len(decoded)-sum(folder.sub_sizes)]
            else:
                # if only one substream
                if len(assigned)==1:
                    sizes=[len(decoded)]
                else:
                    # No sizes specified; cannot split - assume first gets all? Use unpack sizes of last coder? 
                    sizes=[None]*len(assigned)
            pos=0
            for j, idx in enumerate(assigned):
                folder_for_file[idx]=fi
                offset_in_folder[idx]=pos
                sz=sizes[j] if j < len(sizes) else None
                size_in_folder[idx]=sz
                if sz is not None: pos+=sz
    for idx in range(num):
        name=names[idx] if idx < len(names) else ''
        name=name.replace('\\','/')
        has_stream=not empty_stream[idx]
        is_dir=False; is_anti=False
        if not has_stream:
            ef, is_anti = empty_idx_map.get(idx,(None,False))
            if ef is not None:
                is_dir=not ef
            else:
                # infer from attr
                attr=fileinfo['attrs'][idx] if idx < len(fileinfo['attrs']) else None
                if attr is not None and ((attr & 0x10)!=0 or ((attr>>16)&0x4000)!=0):
                    is_dir=True
                else:
                    # If name ends with / also
                    is_dir=name.endswith('/')
            name=name.rstrip('/')
        e=Entry(name,is_dir=is_dir)
        e.archive_type='7z'
        e.anti=is_anti
        if fileinfo['attrs'] and idx < len(fileinfo['attrs']):
            e.win_attr=fileinfo['attrs'][idx]
            if e.win_attr is not None:
                high=(e.win_attr>>16)&0xFFFF
                if high!=0: e.mode=high
                else:
                    e.mode=0o40755 if is_dir else 0o100644
        if e.mode is None:
            e.mode=0o40755 if is_dir else 0o100644
        if fileinfo['mtime'] and idx < len(fileinfo['mtime']): e.mtime_ft=fileinfo['mtime'][idx]
        if fileinfo['atime'] and idx < len(fileinfo['atime']): e.atime_ft=fileinfo['atime'][idx]
        if fileinfo['ctime'] and idx < len(fileinfo['ctime']): e.ctime_ft=fileinfo['ctime'][idx]
        if e.mtime_ft: e.mtime_ns=filetime_to_ns(e.mtime_ft)
        if has_stream:
            fi=folder_for_file.get(idx)
            e.block=fi
            sz=size_in_folder.get(idx)
            off=offset_in_folder.get(idx,0)
            decoded=folder_datas[fi] if fi is not None and fi < len(folder_datas) else b''
            if sz is None:
                # fallback: if single file etc
                sz=len(decoded)-off
            e.size=sz
            e.data=decoded[off:off+sz] if sz is not None else b''
            # CRC
            crc=None
            # sub crc
            if main_streams and fi is not None:
                folder=main_streams.folders[fi]
                assigned=folder_file_assignments[fi]
                if folder.sub_crcs:
                    j=assigned.index(idx) if idx in assigned else None
                    if j is not None and j < len(folder.sub_crcs): crc=folder.sub_crcs[j]
            if crc is None and fileinfo['file_crcs']:
                # file_crcs are indexed by stream file order
                sf_order=[i2 for i2 in range(num) if not empty_stream[i2]]
                if idx in sf_order:
                    pos=sf_order.index(idx)
                    if pos < len(fileinfo['file_crcs']): crc=fileinfo['file_crcs'][pos]
            if crc is None and e.data is not None:
                crc=zlib.crc32(e.data)&0xffffffff
            e.crc=crc
            # packed size: if folder has one file etc, packing display rules later: set packed size as folder pack size if first in folder else None
            # We'll store folder pack size in entry via a dict in archive
            e.packed_size=None
            # method
            if main_streams and fi is not None:
                folder=main_streams.folders[fi]
                meths=[]
                for coder in reversed(folder.coders):
                    short,detail=coder_name_and_detail(coder, detailed=True)
                    meths.append(detail)
                e.method=' '.join(meths)
                e.encrypted=any(c['id']==bytes.fromhex('06f10701') for c in folder.coders)
        else:
            e.size=0; e.packed_size=0; e.data=b'' if not is_dir else None
            if is_dir: e.data=None
            e.method=''; e.block=None
            e.crc=None
        entries.append(e)
    arch.entries=entries
    # Archive-level info
    if main_streams:
        arch.blocks=len(main_streams.folders)
        # methods list: distinct coder methods in order seen? Use per folder reversed coders detailed but without AES cycles/Delta dist for archive
        methods=[]
        for folder in main_streams.folders:
            for coder in reversed(folder.coders):
                short,detail=coder_name_and_detail(coder, detailed=True)
                # archive display strips :cycles for AES and dist for Delta? For LZMA retain
                if coder['id']==bytes.fromhex('06f10701'): m='7zAES'
                elif coder['id']==b'\x03': m='Delta'
                else: m=detail
                if m not in methods: methods.append(m)
        arch.methods=methods
        # solid: if any folder has sub_count>1
        arch.solid='+' if any(f.sub_count>1 for f in main_streams.folders) else '-'
        total_packed=sum((f.pack_size or 0) for f in main_streams.folders)
        arch.total_packed_main=total_packed
        # Assign packed sizes for display: first file entry in each folder gets folder pack size
        for fi,folder in enumerate(main_streams.folders):
            assigned=folder_file_assignments[fi]
            if assigned:
                first_idx=assigned[0]
                entries[first_idx].packed_size=folder.pack_size
                # other entries packed stays None -> display blank
            # block numbering already
    else:
        arch.blocks=0; arch.solid='-'; arch.methods=[]; arch.total_packed_main=0
    return arch, main_streams, None

class SzDataError(Exception):
    def __init__(self,msg,folder=None):
        super().__init__(msg); self.folder=folder

def read_7z(data, path_display, opts, password):
    if len(data)<32 or data[:6]!=b'7z\xbc\xaf\x27\x1c':
        raise ValueError("Not 7z")
    start_crc_stored=struct.unpack_from('<I',data,8)[0]
    start_header=data[12:32]
    if (zlib.crc32(start_header)&0xffffffff)!=start_crc_stored:
        raise ValueError("Header CRC error")
    next_off,next_size,next_crc=struct.unpack_from('<QQI',start_header,0)
    hdr=data[32+next_off:32+next_off+next_size]
    if len(hdr)<next_size:
        raise ValueError("Unexpected end")
    if (zlib.crc32(hdr)&0xffffffff)!=next_crc:
        # May be?? Raise?
        pass
    arch=sz_parse_header_bytes(hdr, data, opts, password, path_display)
    arch.physical_size=len(data)
    # computed headers size
    main_packed=getattr(arch,'total_packed_main',0)
    # If encoded header, include its packed stream (?) headers size = physical - main_packed
    arch.headers_size=len(data)-main_packed
    # But if data has tail
    expected_len=32+next_off+next_size
    if len(data)>expected_len:
        arch.tail_size=len(data)-expected_len
        arch.warnings.append("There are data after the end of archive")
        arch.physical_size=expected_len  # for display Physical Size is official size without tail? In example with tail, Physical Size=146 (without tail) and Tail Size=1
    return arch

# 7z writing
def sz_choose_dict(total_size, level, method_name):
    if total_size<=4096: return 4096
    # round up to (2 or 3)<<k
    cand=4096
    k=11
    while cand<total_size:
        # sequence: 2<<k, 3<<k, 2<<(k+1),3<<(k+1)...
        # generate
        # move
        # Let's generate list
        break
    candidates=[]
    for e in range(11,32):
        candidates.append(2<<e); candidates.append(3<<e)
    candidates.sort()
    for c in candidates:
        if c>=total_size:
            cand=c; break
    else:
        cand=candidates[-1]
    # cap by level
    caps={1:1<<18,2:1<<20,3:1<<20,4:1<<22,5:1<<25,6:1<<25,7:1<<25,8:1<<26,9:1<<26}
    cap=caps.get(level,1<<25)
    if cand>cap: cand=cap
    if cand<4096: cand=4096
    return cand

