# ---------- 7z format ----------
def sz_read_num(d,i):
    b=d[i]; i+=1
    if b<0x80: return b,i
    cnt=0; mask=0x80
    while b & mask:
        cnt+=1; mask>>=1
        if cnt>8: break
    if cnt>=8:
        return int.from_bytes(d[i:i+8],'little'), i+8
    high=b & (0xFF >> (cnt+1))
    low=int.from_bytes(d[i:i+cnt],'little'); i+=cnt
    return (high << (8*cnt))|low, i

def sz_write_num(v):
    if v<0x80: return bytes([v])
    for cnt in range(1,8):
        max_bits=8*cnt + (7-cnt)
        if v < (1<<max_bits):
            high=v >> (8*cnt)
            low=v & ((1<<(8*cnt))-1)
            first=((0xFF << (8-cnt)) & 0xFF) | high
            return bytes([first])+low.to_bytes(cnt,'little')
    return b'\xff'+v.to_bytes(8,'little')

def sz_bitvector_encode(bits):
    nbytes=(len(bits)+7)//8
    out=bytearray(nbytes)
    for idx,b in enumerate(bits):
        if b: out[idx//8] |= (0x80 >> (idx%8))
    return bytes(out)
