    if data[:4] in (b'PK\x03\x04',b'PK\x05\x06',b'PK\x07\x08'): return 'zip'
    if data[:3]==b'\x1f\x8b\x08': return 'gzip'
    if data[:3]==b'BZh' and len(data)>=4 and data[3:4].isdigit(): return 'bzip2'
    if data[:6]==b'\xfd7zXZ\x00': return 'xz'
    if data[:4]==b'(\xb5/\xfd': return 'zstd'
    if data[:4]==b'MSCF': return 'cab'
    if len(data)>265 and data[257:262]==b'ustar': return 'tar'
    return None

def open_archive_from_bytes(data, path_display, opts, password, forced_type=None):
    # returns Archive
    detected=detect_content_type(data)
    ext_type=type_from_extension(path_display) if path_display else None
    ftype=forced_type.lower() if forced_type else None
    if ftype:
        alias={'gz':'gzip','bz2':'bzip2'}
        ftype=alias.get(ftype,ftype)
    # If forced type is specified
    if ftype:
        if ftype not in ('7z','zip','tar','gzip','bzip2','xz','lzma','lzma86','zstd','cab','split','hash'):
            raise ArchiveOpenFailure("Unsupported archive type", kind='unsupported_type', forced_type=ftype)
        use_type=ftype
        # If content is different and forced is ... original tries forced first, if it can't parse, error as [forced]; but if content signature is another archive, maybe it warns and uses other? For -tzip on 7z file, test?
        # We'll if detected and detected != ftype, still attempt forced; if fails, raise cannot as type.
        try:
            arch=read_by_type(data, path_display, opts, password, use_type)
            return arch
        except NeedPassword:
            raise
        except HeadersEncryptedError:
            raise ArchiveOpenFailure("Cannot open encrypted archive. Wrong password?", kind='enc_headers')
        except Exception as e:
            raise ArchiveOpenFailure(str(e), kind='cannot_as_type', forced_type=use_type)
    # No forced
    if detected:
        try:
            arch=read_by_type(data, path_display, opts, password, detected)
            if ext_type and ext_type!=detected and ext_type in ('7z','zip','tar','gzip','bzip2','xz','lzma'):
                # open warning
                arch.props['open_warning']=ext_type
            return arch
        except NeedPassword:
            raise
        except HeadersEncryptedError:
            raise ArchiveOpenFailure("Cannot open encrypted archive. Wrong password?", kind='enc_headers')
        except Exception as e:
            # if detected parser failed, maybe tar fallback
            if detected=='tar':
                raise ArchiveOpenFailure(str(e), kind='not_archive')
            raise ArchiveOpenFailure(str(e), kind='not_archive')
    # No signature: try extension
    if ext_type:
        if ext_type=='tar':
            try: return read_by_type(data, path_display, opts, password, 'tar')
            except Exception as e: raise ArchiveOpenFailure(str(e), kind='cannot_as_type', forced_type='tar')
        if ext_type in ('lzma','lzma86'):
            try: return read_by_type(data, path_display, opts, password, ext_type)
            except Exception as e: raise ArchiveOpenFailure(str(e), kind='cannot_as_type', forced_type=ext_type)
        # Other extension types but content bad: Cannot open as [ext]
        raise ArchiveOpenFailure("Is not archive", kind='cannot_as_type', forced_type=ext_type)
