    try:
        # tarfile check: ustar missing but old tar checksum - use read_tar which will attempt
        return read_by_type(data, path_display, opts, password, 'tar')
    except Exception:
        pass
    raise ArchiveOpenFailure("Cannot open the file as archive", kind='not_archive')

def read_by_type(data, path_display, opts, password, typ):
    if typ=='7z': return read_7z(data, path_display, opts, password)
    if typ=='zip': 
        arch=read_zip(data, path_display, opts, password)
        if arch.type!='zip': raise ValueError("not zip")
        return arch
    if typ=='tar': return read_tar(data, path_display, opts, password)
    if typ=='gzip': return read_gzip(data, path_display, opts, password)
    if typ=='bzip2': return read_bzip2(data, path_display, opts, password)
    if typ=='xz': return read_xz(data, path_display, opts, password)
    if typ=='lzma': 
        arch=read_lzma_alone(data, path_display, opts, password)
        # parse props dict
        if len(data)>=5:
            dsize=struct.unpack('<I',data[1:5])[0]
            arch.methods=[f"LZMA:{dict_display(dsize)}"]
            if arch.entries: arch.entries[0].method=arch.methods[0]; arch.entries[0]._unknown_size=True
        return arch
    if typ=='zstd': raise ValueError("zstd not implemented")
    if typ=='cab': raise ValueError("cab not implemented")
    raise ValueError(f"Unsupported type {typ}")

def open_archive_file(path, opts, password):
    # Split volumes handling
    base=os.path.basename(path)
    m=re.match(r'^(.*)\.001$', base)
    if m and os.path.exists(path):
        # gather volumes
        prefix=path[:-3]  # includes .? path without 001 -> "....zip."
        # volumes are path with 001,002...
        vols=[]
        i=1
        while True:
            vp=path[:-3]+f"{i:03d}"
            if os.path.exists(vp): vols.append(vp); i+=1
            else: break
        if len(vols)>=1:
            # Only treat as split if stripped name has archive extension or multiple volumes or content doesn't start with... Real 7z treats .001 as split always
            combined=b''.join(open(v,'rb').read() for v in vols)
            inner_name=m.group(1)
            # inner_name is basename without .001, e.g. vol.zip
            inner_path=inner_name
            try:
                inner=open_archive_from_bytes(combined, inner_path, opts, password, forced_type=opts.type)
            except ArchiveOpenFailure:
                # If combined content fails, maybe the .001 itself is a normal archive (e.g. 7z volume?) still treat as split? We'll re-raise
                raise
            inner.is_split_wrapper=True
            inner.volumes=len(vols)
            inner.total_physical=len(combined)
            inner.physical_size=len(open(path,'rb').read())
            inner.split_first_path=path
            inner.inner_name=inner_name
            # Keep entries from inner
            return inner
    # normal
    with open(path,'rb') as f: data=f.read()
    arch=open_archive_from_bytes(data, path, opts, password, forced_type=opts.type)
    arch.file_data=data
    return arch

