def archive_strict_match(pattern, path, case_sensitive=True):
    # pattern matching for items in archive
    if pattern.endswith('/') : pattern=pattern.rstrip('/')
    if path.endswith('/') : path=path.rstrip('/')
    # exact or prefix directory
    if '*' not in pattern and '?' not in pattern:
        if not case_sensitive:
            if path.lower()==pattern.lower() or path.lower().startswith(pattern.lower()+'/'): return True
        else:
            if path==pattern or path.startswith(pattern+'/'): return True
        return False
    # wildcard full segment match
    if wildcard_match_path_segments(pattern, path, case_sensitive):
        return True
    # wildcard matches a directory prefix of path
    pparts=pattern.split('/'); nparts=path.split('/')
    if len(pparts)<len(nparts):
        prefix='/'.join(nparts[:len(pparts)])
        if wildcard_match_path_segments(pattern, prefix, case_sensitive): return True
    return False

def wildcard_match_path_segments(pattern, path, case_sensitive=True):
    pparts=pattern.split('/'); nparts=path.split('/')
    if len(pparts)!=len(nparts): return False
    return all(wildcard_match_component(a,b,case_sensitive) for a,b in zip(pparts,nparts))

