    recur = opts.recurse_mode in (True,'0')
    if recur:
        for root,dirs,files in os.walk(directory):
            for fn in files:
                path=os.path.join(root,fn)
                rel=path if directory!='.' else fn if root=='.' else os.path.join(root,fn)
