def format_slt_datetime(e):
    dt=e.mtime_datetime()
    if not dt: return ""
    base=dt.strftime("%Y-%m-%d %H:%M:%S")
    # filetime based
    if getattr(e,'mtime_ft',None):
        frac=(e.mtime_ft % 10000000)
        return f"{base}.{frac:07d}"
    if e.archive_type=='tar':
        if e.mtime_ns is not None and e.mtime_ns % 1000000000 !=0:
            frac=f"{e.mtime_ns % 1000000000:09d}".rstrip('0')
            return f"{base}.{frac}"
        return base
    if e.archive_type=='zip':
        # if we have _zip_dt exact and no ft, no fractional
        return base
    return base

