def validate_update_options(opts):
    # Returns True if valid, otherwise prints post-banner cmd error
    raw=opts.update_options_raw
    if raw is None: return True
    # Raw examples: "", "-", "p0", "q0", etc, "!newname"
    # Valid chars pattern: sequences of [pqrx yz][0-9] etc, or '-' at start, or '!name'
    # Simplistic: if raw contains letters other than pqrxyz and digits and '!...' then invalid with remainder from first bad char
    # Original error for '-unknown': raw="nknown", message: "incorrect update switch command\nnknown"
    s=raw
    i=0
    if s.startswith('-'): i=1
    valid=True
    while i < len(s):
        c=s[i]
        if c=='!':
            # rest is archive name
            opts.update_new_archive=s[i+1:]
            break
        if c in 'pqrx yz':
            # Actually options: p#, q#, r#, x#, y#, z#
            if c not in 'pq rxyz'.replace(' ',''):
                valid=False; break
            i+=1
            # optional digit(s) (?) one char digit or '-'
            if i < len(s) and (s[i].isdigit() or s[i]=='-'): i+=1
            else:
                # some allow no digit?
                pass
        else:
            valid=False; break
    if not valid:
        print_cmdline_error(f"incorrect update switch command\n{s[i:] if i < len(s) else s}")
        return False
    return True

