def next_auto_name(dest):
    dirn=os.path.dirname(dest); base=os.path.basename(dest)
    # split extension: last dot not at start
    if '.' in base and not base.startswith('.'):
        stem, ext=base.rsplit('.',1); ext='.'+ext
    else:
        stem,ext=base,''
    i=1
    while True:
        cand=os.path.join(dirn,f"{stem}_{i}{ext}") if dirn else f"{stem}_{i}{ext}"
        if not os.path.lexists(cand): return cand
        i+=1

def compute_hash_by_name(method, data):
    m=method.lower()
    if m=='sha256': return hashlib.sha256(data).hexdigest()
    if m=='sha1': return hashlib.sha1(data).hexdigest()
    if m=='sha512': return hashlib.sha512(data).hexdigest()
    if m=='md5': return hashlib.md5(data).hexdigest()
    if m=='sha384': return hashlib.sha384(data).hexdigest()
    if m=='sha224': return hashlib.sha224(data).hexdigest()
    if m in ('sha512-224','sha512_224'): return hashlib.new('sha512_224',data).hexdigest()
    if m in ('sha512-256','sha512_256'): return hashlib.new('sha512_256',data).hexdigest()
    if m.startswith('sha3'): return hashlib.new(m.replace('-','_') if False else m, data).hexdigest()
    if m=='crc32': return f"{zlib.crc32(data)&0xffffffff:08X}"
    if m=='crc64': return f"{crc64(data):016X}"
    if m=='xxh64': return f"{xxh64(data):016X}"
    if m=='blake2s': return hashlib.blake2s(data).hexdigest()
    if m=='blake2b': return hashlib.blake2b(data).hexdigest()
    # fallback sha256
    return hashlib.sha256(data).hexdigest()

