def do_rename(opts):
    if not opts.archive_name:
        print_cmdline_error("Cannot find archive name"); return 7
    patterns=opts.raw_positionals
    if len(patterns)%2==1:
        print_cmdline_error(f"There is no second file name for rename pair:\n{patterns[-1]}"); return 7
    typ, final_name=type_from_archive_name_for_create(opts.archive_name, opts.type)
