    arch.path_display=final_name; print_info_block(arch)
    if arch.type in CREATABLE_TYPES and not opts.type: typ=arch.type
    # rename
    entries=arch.entries
    for i in range(0,len(patterns),2):
        old,new=patterns[i],patterns[i+1]
        for e in entries:
            if archive_strict_match(old, e.name, opts.case_sensitive) or e.name==old:
                # rename logic
                if e.name==old:
                    e.name=new
                elif old in e.name and '*' not in old:
                    # prefix dir rename
                    if e.name.startswith(old.rstrip('/')+'/'):
                        e.name=new.rstrip('/')+e.name[len(old.rstrip('/')):]
                    else:
                        e.name=new
                else:
                    # wildcard rename: if new contains *, substitute matched?
                    if '*' in new:
                        # extract part matched by * in old: simple: use basename stem
                        # Build regex from old with capture
                        regex='^'
                        for ch in old:
                            if ch=='*': regex+='(.*)'
                            elif ch=='?': regex+='(.)'
                            else: regex+=re.escape(ch)
                        regex+='$'
                        m=re.match(regex, e.name)
                        if m:
                            repl=m.group(1) if m.groups() else ''
                            e.name=new.replace('*', repl)
                        else: e.name=new
                    else:
                        e.name=new
    kfolders=sum(1 for e in entries if e.is_dir); kfiles=len(entries)-kfolders; ktotal=sum(e.size or 0 for e in entries)
    out(f"Updating archive: {final_name}\n\n\n")
