    if typ in ('gzip','bzip2','xz'):
        files=[e for e in final if not e.is_dir]
        if len(files)!=1:
            print_system_error("E_INVALIDARG : One or more arguments are invalid"); return 2
    try: data_bytes=write_archive_bytes(typ, final, opts, opts.password)
    except Exception as e:
        print_system_error("E_INVALIDARG : One or more arguments are invalid"); return 2
    with open(final_name,'wb') as f: f.write(data_bytes)
