        return pw
    return None

def write_archive_bytes(typ, entries, opts, password):
    if typ=='7z': return write_7z(entries, opts, password)
    if typ=='zip': return write_zip(entries, opts, password)
    if typ=='tar': return write_tar(entries, opts, password)
    if typ=='gzip':
        files=[e for e in entries if not e.is_dir]
        if len(files)!=1: raise FatalError('system',"E_INVALIDARG : One or more arguments are invalid")
        return write_gzip(files[0], opts)
    if typ=='bzip2':
        files=[e for e in entries if not e.is_dir]
        if len(files)!=1: raise FatalError('system',"E_INVALIDARG : One or more arguments are invalid")
        return bz2.compress(files[0].data or b'')
    if typ=='xz':
        files=[e for e in entries if not e.is_dir]
        if len(files)!=1: raise FatalError('system',"E_INVALIDARG : One or more arguments are invalid")
        raw=files[0].data or b''
        dict_size=sz_choose_dict(len(raw), opts.mx if opts.mx is not None else 5, 'LZMA2')
        return lzma.compress(raw, format=lzma.FORMAT_XZ, check=lzma.CHECK_CRC32, filters=[{'id':lzma.FILTER_LZMA2,'dict_size':dict_size}])
    if typ=='hash':
        # determine method
        method=opts._hash_method if hasattr(opts,'_hash_method') else 'sha256'
        lines=[]
        for e in sorted(entries, key=lambda x:x.name):
            if e.is_dir: continue
            data=e.data or b''
            hv=compute_hash_by_name(method, data)
            # original: CRC32 uppercase, others lower (hashlib lower, crc function uppercase). For sha* lower, crc32 upper from function.
            lines.append(f"{hv}  {e.name}\n")
        return ''.join(lines).encode('utf-8')
    raise FatalError('error',"Unsupported archive type")

