new="""def load_zip_entry_data(arch, entry, opts, password):
    if getattr(entry,'_local_offset',None) is not None:
        data=arch._zip_data if hasattr(arch,'_zip_data') else None
        if data is None:
            # stored in file_data
            data=getattr(arch,'file_data',b'')
        off=entry._local_offset
        if data[off:off+4]!=b'PK\\x03\\x04': raise ZipReadError('Bad local header')
        nlen, elen=struct.unpack_from('<HH', data, off+26)
        flag=entry._local_flag; method=entry._local_method
        start=off+30+nlen+elen
        # determine compressed length
        compsize=entry.packed_size
        if flag & 0x08 or not compsize:
            # search next PK signature
            nxt=len(data)
            for sig in (b'PK\\x03\\x04', b'PK\\x01\\x02', b'PK\\x05\\x06', b'PK\\x07\\x08'):
                i=data.find(sig, start)
                if i!=-1 and i<nxt: nxt=i
            # if data descriptor PK0708 found, data ends at its start; else if next is a header, there may be a descriptor without signature (12/16 bytes) - approximate with search
            if data[nxt:nxt+4]==b'PK\\x07\\x08':
                comp=data[start:nxt]
            else:
                comp=data[start:nxt]
                # strip possible descriptor (crc+comp+uncomp =12) if method requires? Only if flag set and descriptor not signed: assume last 12 bytes are descriptor if sizes match uncompressed after decompress fails - try full first
        else:
            comp=data[start:start+compsize]
        # decrypt if needed
        if entry.encrypted:
            if password is None: raise NeedPassword()
            zc=ZipCrypto(password.encode())
            dec=zc.decrypt(comp)
            comp=dec[12:]
        if method==0: raw=comp
        elif method==8: raw=zlib.decompress(comp,-15)
        elif method==12: raw=bz2.decompress(comp)
        elif method==14: raw=lzma.decompress(comp, format=lzma.FORMAT_ALONE)
        else: raise ZipReadError(f'Unsupported zip method {method}')
        entry.data=raw; entry._local_offset=None
        return raw
    if not getattr(entry,'_zip_pending',False):
        return entry.data"""
