import hashlib, subprocess, struct, sys, itertools
path='/tmp/copyenc/copyenc.7z'; data=open(path,'rb').read(); off,size,_=struct.unpack('<QQI', data[12:32]); packed=data[32:32+off]
props=bytes.fromhex('530fd0fb2ba13800e5b1218db6d280f352a4'); plain=b'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'+b'\x00'*12
def check(key,iv,label):
    p=subprocess.run(['openssl','enc','-d','-aes-256-cbc','-K',key.hex(),'-iv',iv.hex(),'-nopad'], input=packed, capture_output=True)
    if p.stdout==plain: print('SUCCESS',label); sys.exit(0)
for pwname,pw in [('u16','password'.encode('utf-16le')),('u8',b'password'),('u32','password'.encode('utf-32le'))]:
 for sname,salt in [('k8',props[2:10]),('k16',props[2:18]),('empty',b''),('k1',props[2:3])]:
  for order in itertools.permutations(['pw','salt','ctr']):
   for fmt,start in [('8le',0),('8le',1),('8be',0),('4le',0),('4be',0),('1byte',0)]:
    h=hashlib.sha256()
    for i in range(start, start+(1<<19)):
        if fmt=='8le': ctr=struct.pack('<Q',i)
        elif fmt=='8be': ctr=struct.pack('>Q',i)
        elif fmt=='4le': ctr=struct.pack('<I',i)
        elif fmt=='4be': ctr=struct.pack('>I',i)
        else: ctr=bytes([i & 0xff])
        comp={'pw':pw,'salt':salt,'ctr':ctr}
        for part in order: h.update(comp[part])
    key=h.digest()
    for iname,iv in [('secondz',props[10:18]+b'\x00'*8),('zero',b'\x00'*16),('all',props[2:18])]:
        check(key,iv,f'{pwname} {sname} {order} {fmt}{start} {iname}')
  print('done order set',pwname,sname)
print('none')
